import json
from pathlib import Path

import numpy as np
import pytest

from sensor_fusion_ml.data_engine.contracts import DataContract, SensorModality, TimeUnit
from sensor_fusion_ml.data_engine.loader import load_manifest, validate_dataset, validation_passed


def _write_manifest(root: Path, *, payload_path="position.npy"):
    np.save(root / "position.npy", np.asarray([1.0, 2.0, 0.1, 0.2], dtype=np.float64))
    manifest = {
        "name": "local-test-fixture",
        "license": "synthetic test fixture",
        "provenance": "generated by unit test",
        "time_unit": "seconds",
        "sequences": [{
            "sequence_id": "sequence-a",
            "split": "train",
            "frames": [
                {"frame_id": "f0", "timestamp": 0.0, "observations": [
                    {"modality": "gnss", "path": payload_path, "format": "npy", "frame": "world"}
                ]},
                {"frame_id": "f1", "timestamp": 0.1, "observations": [
                    {"modality": "gnss", "path": payload_path, "format": "npy", "frame": "world"}
                ]},
            ],
        }],
    }
    path = root / "manifest.json"
    path.write_text(json.dumps(manifest), encoding="utf-8")
    return path


def _contract():
    return DataContract(
        name="test-contract",
        required_modalities=[SensorModality.GNSS],
        time_unit=TimeUnit.SECONDS,
        min_frames=2,
        max_time_gap_s=0.2,
    )


def test_load_manifest_and_validate_local_npy(tmp_path):
    manifest = _write_manifest(tmp_path)
    dataset = load_manifest(manifest)
    assert dataset.name == "local-test-fixture"
    assert dataset.splits == {"train": ["sequence-a"]}
    assert len(dataset.sequences["sequence-a"]) == 2
    assert np.allclose(dataset.sequences["sequence-a"][0].observations[SensorModality.GNSS].data,
                       [1.0, 2.0, 0.1, 0.2])
    reports = validate_dataset(dataset, _contract())
    assert validation_passed(reports)


def test_loader_rejects_path_traversal(tmp_path):
    outside = tmp_path.parent / "outside.npy"
    np.save(outside, np.asarray([1.0]))
    manifest = _write_manifest(tmp_path, payload_path="../outside.npy")
    with pytest.raises(ValueError, match="escapes dataset root"):
        load_manifest(manifest)


def test_loader_rejects_missing_payload(tmp_path):
    manifest = _write_manifest(tmp_path, payload_path="missing.npy")
    with pytest.raises(FileNotFoundError, match="does not exist"):
        load_manifest(manifest)


def test_loader_rejects_unknown_split(tmp_path):
    manifest = _write_manifest(tmp_path)
    data = json.loads(manifest.read_text(encoding="utf-8"))
    data["sequences"][0]["split"] = "validation"
    manifest.write_text(json.dumps(data), encoding="utf-8")
    with pytest.raises(ValueError, match="split must be train, val, or test"):
        load_manifest(manifest)


def test_loader_does_not_allow_pickle_payloads(tmp_path):
    manifest = _write_manifest(tmp_path)
    # A non-numeric object array would require pickle; the loader must not enable it.
    np.save(tmp_path / "object.npy", np.asarray([{"x": 1}], dtype=object))
    data = json.loads(manifest.read_text(encoding="utf-8"))
    data["sequences"][0]["frames"][0]["observations"][0]["path"] = "object.npy"
    manifest.write_text(json.dumps(data), encoding="utf-8")
    with pytest.raises(ValueError):
        load_manifest(manifest)
